typedef struct SkCleanup {
    void** ptr;
    int type;
    struct SkCleanup* next;
} SkCleanup;

typedef struct SkTryFrame {
    jmp_buf env;
    void* error;
    struct SkTryFrame* prev;
    SkCleanup* cleanup;
} SkTryFrame;

SkTryFrame* sk_try_stack = NULL;

void sk_any_free(sk_any* a) {
    if (a->type == 1 && a->data.s) { free(a->data.s); a->data.s = NULL; }
    else if (a->type == 5 && a->data.p) { sk_array_deep_free((sk_array*)a->data.p); a->data.p = NULL; }
    a->type = -1;
}

void sk_try_register(void** ptr, int type) {
    if (sk_try_stack == NULL) return;
    SkCleanup* c = malloc(sizeof(SkCleanup));
    c->ptr = ptr;
    c->type = type;
    c->next = sk_try_stack->cleanup;
    sk_try_stack->cleanup = c;
}

void sk_try_cleanup(SkTryFrame* frame) {
    SkCleanup* c = frame->cleanup;
    while (c) {
        if (*c->ptr != NULL) {
            switch (c->type) {
                case 0: free(*c->ptr); break;
                case 1: sk_array_free(*(sk_array**)c->ptr); break;
                case 2: sk_any_free((sk_any*)c->ptr); break;
            }
            *c->ptr = NULL;
        }
        SkCleanup* next = c->next;
        free(c);
        c = next;
    }
    frame->cleanup = NULL;
}

void sk_try_push(SkTryFrame* frame) {
    frame->prev = sk_try_stack;
    frame->cleanup = NULL;
    frame->error = NULL;
    sk_try_stack = frame;
}

void sk_try_pop(SkTryFrame* frame) {
    SkCleanup* c = frame->cleanup;
    while (c) {
        SkCleanup* next = c->next;
        free(c);
        c = next;
    }
    frame->cleanup = NULL;
    sk_try_stack = frame->prev;
}

void sk_error_free(void* err) {
    if (!err) return;
    sk_string* msg = (sk_string*)((char*)err + sizeof(const char*));
    if (msg->value) { free(msg->value); msg->value = NULL; }
    free(err);
}

void sk_throw(void* err, const char* file, int line, int col) {
    if (sk_try_stack == NULL) {
        const char* __type = *(const char**)err;
        if (sk_call_stack_top > 0) {
            SkCallFrame* top = &sk_call_stack[sk_call_stack_top - 1];
            fprintf(stderr, "Panicked with error (%s) at %s:%d:%d (thrown from %s:%d:%d)\n",
                __type, top->file, top->line, top->col, file, line, col);
        } else {
            fprintf(stderr, "Panicked with error (%s) at %s:%d:%d\n", __type, file, line, col);
        }
        exit(1);
    }
    SkTryFrame* frame = sk_try_stack;
    while (frame != NULL) {
        sk_try_cleanup(frame);
        frame = frame->prev;
    }
    sk_try_stack->error = err;
    longjmp(sk_try_stack->env, 1);
}

int sk_error_type_match(const char* actual, const char* expected) {
    size_t len = strlen(expected);
    if (strncmp(actual, expected, len) != 0) return 0;
    return actual[len] == '\0' || actual[len] == '.';
}

// Inline C code
// UTF-8: декодирование одного символа
// Возвращает codepoint, а через *len — длину в байтах
unsigned int __sk__utf8__decode(const char *s, int *len) {
    unsigned char c = (unsigned char)s[0];
    if (c < 0x80) { *len = 1; return c; }
    if ((c & 0xE0) == 0xC0) {
        *len = 2;
        return ((c & 0x1F) << 6) | (s[1] & 0x3F);
    }
    if ((c & 0xF0) == 0xE0) {
        *len = 3;
        return ((c & 0x0F) << 12) | ((s[1] & 0x3F) << 6) | (s[2] & 0x3F);
    }
    if ((c & 0xF8) == 0xF0) {
        *len = 4;
        return ((c & 0x07) << 18) | ((s[1] & 0x3F) << 12) | ((s[2] & 0x3F) << 6) | (s[3] & 0x3F);
    }
    *len = 1;
    return c;
}

// UTF-8: кодирование codepoint в буфер
// Возвращает длину в байтах
int __sk__utf8__encode(unsigned int cp, char *out) {
    if (cp < 0x80) {
        out[0] = (char)cp;
        return 1;
    }
    if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        return 2;
    }
    if (cp < 0x10000) {
        out[0] = (char)(0xE0 | (cp >> 12));
        out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (char)(0x80 | (cp & 0x3F));
        return 3;
    }
    out[0] = (char)(0xF0 | (cp >> 18));
    out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
    out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
    out[3] = (char)(0x80 | (cp & 0x3F));
    return 4;
}

// Приведение одного codepoint к верхнему регистру
unsigned int __sk__utf8__to_upper(unsigned int cp) {
    if (cp < 0x80) return (unsigned int)toupper((int)cp);
    if (cp >= 0x430 && cp <= 0x44F) return cp - 0x20;
    if (cp == 0x451) return 0x401;
    if (cp >= 0xE0 && cp <= 0xFE && cp != 0xF7) return cp - 0x20;
    if (cp == 0xFF) return 0x178;
    if (cp >= 0x3B1 && cp <= 0x3C9 && cp != 0x3C2) return cp - 0x20;
    if (cp == 0x3C2) return 0x3A3;
    return cp;
}

// Приведение одного codepoint к нижнему регистру
unsigned int __sk__utf8__to_lower(unsigned int cp) {
    if (cp < 0x80) return (unsigned int)tolower((int)cp);
    if (cp >= 0x410 && cp <= 0x42F) return cp + 0x20;
    if (cp == 0x401) return 0x451;
    if (cp >= 0xC0 && cp <= 0xDE && cp != 0xD7) return cp + 0x20;
    if (cp == 0x178) return 0xFF;
    if (cp >= 0x391 && cp <= 0x3A9) return cp + 0x20;
    return cp;
}

// Общая функция изменения регистра
char* __sk__utf8__change_case(const char *src, int mode) {
    size_t src_len = strlen(src);
    char *out = malloc(src_len * 4 + 1);
    if (!out) return NULL;

    size_t i = 0, o = 0;
    int word_start = 1;

    while (src[i]) {
        int char_len = 0;
        unsigned int cp = __sk__utf8__decode(&src[i], &char_len);

        unsigned int new_cp = cp;
        switch (mode) {
            case 0: new_cp = __sk__utf8__to_lower(cp); break;
            case 1: new_cp = __sk__utf8__to_upper(cp); break;
            case 2:
                if (word_start) new_cp = __sk__utf8__to_upper(cp);
                else new_cp = __sk__utf8__to_lower(cp);
                word_start = (cp == ' ' || cp == '\t' || cp == '\n' ||
                              cp == '\r' || cp == '.' || cp == ',' ||
                              cp == '!' || cp == '?' || cp == ';' ||
                              cp == ':' || cp == '-' || cp == '(' ||
                              cp == ')' || cp == '[' || cp == ']');
                break;
        }

        o += __sk__utf8__encode(new_cp, &out[o]);
        i += char_len;
    }

    out[o] = '\0';
    return out;
}

// Поиск подстроки (байтовый, но для UTF-8 корректный,
// т.к. границы codepoint в UTF-8 не пересекаются)
int __sk__str_find(const char *haystack, const char *needle) {
    const char *p = strstr(haystack, needle);
    if (!p) return -1;
    return (int)(p - haystack);
}



