        snprintf(code_buf, sizeof(code_buf), "\033[38;5;%dm", code.value);
        size_t clen = strlen(code_buf);
        size_t tlen = strlen(text.value);
        char* buf = malloc(clen + tlen + 4 + 1);
        memcpy(buf, code_buf, clen);
